dashboard.definition:
{
	"dataSources": {
		"ds_Rq4kit9c": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"cisco_wl_ap_stats_rx_util_percentage\") prestats=true WHERE \"index\"=\"cisco_metrics\" rrm_measurement_wtp_mac=* span=60s BY rrm_measurement_wtp_mac\n| timechart latest(\"cisco_wl_ap_stats_rx_util_percentage\") span=60s useother=false BY rrm_measurement_wtp_mac\n| fields - _span*",
				"queryParameters": {
					"earliest": "-1h",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "RX Utilization 2 search"
		},
		"ds_TIATKkZy": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"cisco_wl_ap_stats_tx_util_percentage\") prestats=true WHERE \"index\"=\"cisco_metrics\" rrm_measurement_radio_slot_id=0 rrm_measurement_wtp_mac=* span=60s BY rrm_measurement_wtp_mac\n| timechart latest(\"cisco_wl_ap_stats_tx_util_percentage\") span=60s useother=false BY rrm_measurement_wtp_mac\n| fields - _span*",
				"queryParameters": {
					"earliest": "-15m",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"name": "RX Utilization - Line chart search"
		},
		"ds_xKKkiKAr": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"cisco_wl_ap_stats_rx_util_percentage\") prestats=true WHERE \"index\"=\"cisco_metrics\" span=60s BY rrm_measurement_wtp_mac\n| eval radio_mac=rrm_measurement_wtp_mac\n| stats count() BY radio_mac\n| lookup cisco_ap_mac_radio_mac.csv radio_mac OUTPUT ap_mac\n| lookup cisco_ap_mac_name.csv ap_mac OUTPUT ap_name\n| search ap_name=*\n| table ap_name radio_mac",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "ap_search"
		}
	},
	"visualizations": {
		"viz_OIkHF5pI": {
			"type": "splunk.line",
			"options": {
				"yAxisAbbreviation": "auto",
				"y2AxisAbbreviation": "auto",
				"showRoundedY2AxisLabels": false,
				"legendTruncation": "ellipsisMiddle",
				"showY2MajorGridLines": true,
				"xAxisLabelRotation": 0,
				"xAxisTitleVisibility": "show",
				"yAxisTitleVisibility": "show",
				"y2AxisTitleVisibility": "show",
				"showYAxisWithZero": true,
				"yAxisScale": "linear",
				"showOverlayY2Axis": false,
				"y2AxisScale": "inherit",
				"nullValueDisplay": "connect",
				"dataValuesDisplay": "off",
				"seriesColorsByField": {
					"Avg": "#1e93c6",
					"14:16:9d:2f:f8:00": "#1e93c6",
					"38:91:b7:26:d5:a0": "#f2b827",
					"8c:1e:80:a7:50:c0": "#d6563c",
					"dc:8c:37:80:16:80": "#6a5c9e",
					"f0:d8:05:ed:03:60": "#31a35f"
				},
				"lineDashStylesByField": {
					"Avg": "Solid",
					"14:16:9d:2f:f8:00": "Solid",
					"38:91:b7:26:d5:a0": "Solid",
					"8c:1e:80:a7:50:c0": "Solid",
					"dc:8c:37:80:16:80": "Solid",
					"f0:d8:05:ed:03:60": "Solid"
				},
				"showXMajorGridLines": true,
				"showSplitSeries": false,
				"showIndependentYRanges": false,
				"legendMode": "seriesCompare",
				"legendDisplay": "right",
				"lineWidth": 2
			},
			"dataSources": {
				"primary": "ds_Rq4kit9c"
			},
			"title": "RX Utilization 2"
		},
		"viz_sJVGWflV": {
			"type": "splunk.line",
			"options": {
				"yAxisAbbreviation": "auto",
				"y2AxisAbbreviation": "auto",
				"showRoundedY2AxisLabels": false,
				"legendTruncation": "ellipsisMiddle",
				"showY2MajorGridLines": true,
				"xAxisLabelRotation": 0,
				"xAxisTitleVisibility": "show",
				"yAxisTitleVisibility": "show",
				"y2AxisTitleVisibility": "show",
				"showYAxisWithZero": true,
				"yAxisScale": "linear",
				"showOverlayY2Axis": false,
				"y2AxisScale": "inherit",
				"nullValueDisplay": "connect",
				"dataValuesDisplay": "off",
				"seriesColorsByField": {
					"Avg": "#1e93c6",
					"14:16:9d:2f:f8:00": "#1e93c6",
					"38:91:b7:26:d5:a0": "#f2b827",
					"8c:1e:80:a7:50:c0": "#d6563c",
					"dc:8c:37:80:16:80": "#6a5c9e",
					"f0:d8:05:ed:03:60": "#31a35f"
				},
				"lineDashStylesByField": {
					"Avg": "Solid",
					"14:16:9d:2f:f8:00": "Solid",
					"38:91:b7:26:d5:a0": "Solid",
					"8c:1e:80:a7:50:c0": "Solid",
					"dc:8c:37:80:16:80": "Solid",
					"f0:d8:05:ed:03:60": "Solid"
				},
				"showXMajorGridLines": true,
				"showSplitSeries": false,
				"showIndependentYRanges": false,
				"legendMode": "seriesCompare",
				"legendDisplay": "right",
				"lineWidth": 2
			},
			"dataSources": {
				"primary": "ds_TIATKkZy"
			},
			"title": "RX Utilization"
		}
	},
	"applicationProperties": {
		"hideEdit": false,
		"hideExport": false
	},
	"inputs": {
		"input_global_trp": {
			"type": "input.timerange",
			"options": {
				"token": "global_time",
				"defaultValue": "-24h@h,now"
			},
			"title": "Global Time Range"
		},
		"input_wT3WXyIE": {
			"options": {
				"items": ">frame(label, value) | prepend(formattedStatics) | objects()",
				"token": "tk_radio",
				"selectFirstSearchResult": true
			},
			"title": "Access Point",
			"type": "input.dropdown",
			"dataSources": {
				"primary": "ds_xKKkiKAr"
			},
			"context": {
				"formattedConfig": {
					"number": {
						"prefix": ""
					}
				},
				"formattedStatics": ">statics | formatByType(formattedConfig)",
				"statics": [],
				"label": ">primary | seriesByName(\"ap_name\") | renameSeries(\"label\") | formatByType(formattedConfig)",
				"value": ">primary | seriesByName(\"radio_mac\") | renameSeries(\"value\") | formatByType(formattedConfig)"
			}
		}
	},
	"layout": {
		"options": {},
		"globalInputs": [
			"input_global_trp",
			"input_wT3WXyIE"
		],
		"tabs": {
			"items": [
				{
					"layoutId": "layout_1",
					"label": "New tab"
				}
			]
		},
		"layoutDefinitions": {
			"layout_1": {
				"type": "grid",
				"structure": [
					{
						"item": "viz_sJVGWflV",
						"type": "block",
						"position": {
							"x": 0,
							"y": 0,
							"w": 1440,
							"h": 250
						}
					},
					{
						"item": "viz_OIkHF5pI",
						"type": "block",
						"position": {
							"x": 0,
							"y": 250,
							"w": 1440,
							"h": 300
						}
					}
				],
				"options": {
					"width": 1440,
					"height": 960
				}
			}
		}
	},
	"title": "Wireless AP Details",
	"description": "",
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			}
		},
		"visualizations": {
			"global": {
				"showProgressBar": true
			}
		}
	}
}
